namespace ghidra.app.plugin.core.debug.disassemble;

using docking;
using ghidra.app.plugin.core.debug.gui.listing;
using ghidra.app.services;
using ghidra.app.services;
using ghidra.debug.api.platform;
using ghidra.debug.api.platform;
using ghidra.debug.api.tracemgr;
using ghidra.framework.cmd;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.trace.model;
using ghidra.trace.model.program;
using ghidra.trace.model.target;
using ghidra.trace.model.thread;
using ghidra.util.task;

public sealed class CurrentPlatformTraceDisassembleCommand : BackgroundCommand<TraceProgramView> {
	public static readonly string NAME = "Disassemble";

	public record Reqs(DebuggerPlatformMapper mapper, TraceThread thread, TraceObject @object,
			TraceProgramView view) {

		public static Reqs fromView(PluginTool tool, TraceProgramView view) {
			DebuggerTraceManagerService traceManager =
				tool.getService(typeof(DebuggerTraceManagerService));
			DebuggerPlatformService platformService =
				tool.getService(typeof(DebuggerPlatformService));
			if (platformService == null) {
				return null;
			}
			Trace trace = view.getTrace();
			DebuggerCoordinates current = traceManager == null ? DebuggerCoordinates.NOWHERE
					: traceManager.getCurrentFor(trace);
			TraceThread thread = current.getThread();
			TraceObject @object = current.getObject();
			DebuggerPlatformMapper mapper =
				platformService.getMapper(trace, @object, view.getSnap());
			if (mapper == null) {
				return null;
			}
			return new Reqs(mapper, thread, @object, view);
		}

		public static Reqs fromContext(PluginTool tool, ActionContext context) {
			if (!(context is DebuggerListingActionContext lac)) {
				return null;
			}
			return fromView(tool, lac.getProgram());
		}
	}

	private PluginTool tool;
	private AddressSetView set;
	private Reqs reqs;
	private Address address;

	public CurrentPlatformTraceDisassembleCommand(PluginTool tool, AddressSetView set, Reqs reqs,
			Address address) : base(NAME, true, true, false)
    {
		this.tool = tool;
		this.set = set;
		this.reqs = reqs;
		this.address = address;
	}

	/* @Override */
	public bool applyTo(TraceProgramView view, TaskMonitor monitor) {
		DisassemblyResult result = reqs.mapper.disassemble(reqs.thread, reqs.@object, address, set,
			view.getSnap(), monitor);
		if (!result.isSuccess()) {
			tool.setStatusInfo(result.getErrorMessage(), true);
		}
		return true;
	}
}
